package com.vandorlabs.neoforge.screen;
import com.vandorlabs.redstone.ChannelList;
import net.minecraft.nbt.*;
import java.util.*;
/** Immutable standalone control rows; configuration copies exclude active output ownership. */
public record NativeScreenControls(boolean enabled,String title,List<Row> rows) implements com.vandorlabs.screen.ScreenControlOverlay.Contents {
 public static final int STANDALONE_ROWS=8,HALF_ROWS=4,MAX_LABEL=24,MAX_TITLE=32,SLIDER_LABEL=11;
 public static final String DEFAULT_TITLE="REDSTONE CONTROL";
 public NativeScreenControls{Objects.requireNonNull(title);rows=List.copyOf(rows);if(rows.size()>STANDALONE_ROWS)throw new IllegalArgumentException("Too many standalone rows");}
 public record Row(String label,ChannelList channels,boolean slider,boolean pulse,int min,int max,int level,Map<Integer,Integer> levels,ChannelList latched,boolean active,long pulseUntil) implements com.vandorlabs.screen.ScreenControlOverlay.Row {
  public Row{Objects.requireNonNull(label);Objects.requireNonNull(channels);Objects.requireNonNull(latched);levels=Map.copyOf(levels);}
  /** Pulse visibility follows its own deadline; the saved active field is ALL-bank feedback. */
  public boolean active(long now){return pulse?pulseUntil>0&&now<pulseUntil:active;}
  public int selectedSegment(){return com.vandorlabs.persistence.SignalControlData.stepForLevel(level,min,max);}
  public int segmentValue(int index){return com.vandorlabs.persistence.SignalControlData.levelForStep(index,min,max);}
  public int latchedLevel(int channel){return levels.getOrDefault(channel,latched.contains(channel)?15:0);}
  private void choices(CompoundTag tag){tag.putString("Label",label);tag.putIntArray("RedstoneChannels",channels.toArray());tag.putBoolean("Slider",slider);tag.putBoolean("Pulse",pulse);tag.putInt("Min",min);tag.putInt("Max",max);}
  private void saved(CompoundTag tag){choices(tag);int[] values=new int[channels.size()];for(int i=0;i<values.length;i++)values[i]=latchedLevel(channels.get(i));tag.putIntArray("Levels",values);tag.putInt("Level",level);tag.putLong("PulseUntil",pulseUntil);tag.putIntArray("LatchedChannels",latched.toArray());tag.putBoolean("Active",active);}
 }
 private static boolean validText(String text,int length){if(text==null||text.length()>length)return false;for(int i=0;i<text.length();i++)if(Character.isISOControl(text.charAt(i))||text.charAt(i)=='\u00a7')return false;return true;}
 public static boolean validTitle(String title){return validText(title,MAX_TITLE);}public static boolean validLabel(String label){return validText(label,MAX_LABEL)&&!label.trim().isEmpty();}
 private static ChannelList channels(CompoundTag tag,String key,ChannelList fallback){if(!tag.contains(key,Tag.TAG_INT_ARRAY))return fallback;try{return ChannelList.of(tag.getIntArray(key));}catch(IllegalArgumentException malformed){return fallback;}}
 public static NativeScreenControls read(CompoundTag root,int standaloneCapacity){if(standaloneCapacity!=STANDALONE_ROWS&&standaloneCapacity!=HALF_ROWS)throw new IllegalArgumentException("Invalid standalone capacity");List<Row> rows=new ArrayList<>();ListTag list=root.getList("Rows",Tag.TAG_COMPOUND);for(int i=0;i<Math.min(STANDALONE_ROWS,list.size());i++){CompoundTag entry=list.getCompound(i);String label=entry.getString("Label");if(!validLabel(label))continue;ChannelList channels=channels(entry,"RedstoneChannels",ChannelList.EMPTY);boolean pulse=entry.getBoolean("Pulse"),slider=!pulse&&entry.getBoolean("Slider");int max=entry.contains("Max",Tag.TAG_INT)?Math.max(3,Math.min(15,entry.getInt("Max"))):15,low=entry.getInt("Min"),min=Math.max(1,Math.min(max-2,low==0?5:low));int[] saved=entry.getIntArray("Levels");Map<Integer,Integer> levels=new HashMap<>();for(int j=0;j<Math.min(saved.length,channels.size());j++)levels.put(channels.get(j),Math.max(0,Math.min(15,saved[j])));rows.add(new Row(label,channels,slider,pulse,min,max,Math.max(0,Math.min(15,entry.getInt("Level"))),levels,channels(entry,"LatchedChannels",ChannelList.EMPTY).intersect(channels),entry.getBoolean("Active"),pulse?Math.max(0,entry.getLong("PulseUntil")):0));}if(rows.size()>standaloneCapacity)rows=new ArrayList<>(rows.subList(0,standaloneCapacity));return new NativeScreenControls(root.getBoolean("Enabled"),root.contains("Title",Tag.TAG_STRING)&&validTitle(root.getString("Title"))?root.getString("Title"):DEFAULT_TITLE,rows);}
 public static boolean validConfiguration(CompoundTag root){if(!validTitle(root.getString("Title")))return false;ListTag rows=root.getList("Rows",Tag.TAG_COMPOUND);if(rows.size()>STANDALONE_ROWS)return false;for(int i=0;i<rows.size();i++){CompoundTag row=rows.getCompound(i);if(!validLabel(row.getString("Label"))||row.getBoolean("Pulse")&&row.getBoolean("Slider"))return false;if(row.getBoolean("Slider")&&(row.getString("Label").length()>SLIDER_LABEL||row.getInt("Min")<0||row.getInt("Max")>15||row.getInt("Min")>row.getInt("Max")))return false;}return true;}
 public CompoundTag configuration(){CompoundTag root=new CompoundTag();root.putBoolean("Enabled",enabled);root.putString("Title",title);ListTag list=new ListTag();for(Row row:rows){CompoundTag entry=new CompoundTag();row.choices(entry);list.add(entry);}root.put("Rows",list);return root;}
 public void write(CompoundTag root){ListTag old=root.getList("Rows",Tag.TAG_COMPOUND),list=new ListTag();for(int i=0;i<rows.size();i++){CompoundTag entry=i<old.size()?old.getCompound(i).copy():new CompoundTag();rows.get(i).saved(entry);list.add(entry);}root.putBoolean("Enabled",enabled);root.putString("Title",title);root.put("Rows",list);}
 public static final class Saved{private final CompoundTag original;public final NativeScreenControls controls;public Saved(CompoundTag root,int standaloneCapacity){original=root.copy();controls=read(original,standaloneCapacity);}public CompoundTag unchanged(){return original.copy();}public CompoundTag edited(NativeScreenControls next){CompoundTag root=original.copy();if(!next.equals(controls))next.write(root);return root;}}
}
